/*
 * Ambient types for the build-time virtual module
 * `virtual:doc-kitty/route-shaping` (generated by `routeShapingIntegration` in
 * `config.ts`): the data the toolkit's Starlight route middleware reads at
 * module scope. Kept under `lib/` so both the toolkit's and a consuming site's
 * `lib/**` type-check include pick it up without a triple-slash reference.
 */
declare module 'virtual:doc-kitty/route-shaping' {
  export const routeShaping: {
    /** Normalised site base: `''` or `/prefix`. */
    base: string;
    /** False when the consumer supplied their own sidebar. */
    shapeSidebar: boolean;
    /** False when the site switched prev/next links off. */
    pagination: boolean;
    /** Directory path → index-page metadata, as sorted map entries. */
    directoryMeta: Array<[string, import('./route-shaping.js').DirectoryMeta]>;
    /** Directories whose index page exists but is not published. */
    unpublishedDirs: string[];
  };
}
